export const clamp=(x,a,b)=>Math.min(b,Math.max(a,x));
export function formatTime(seconds,decimal=false){if(!Number.isFinite(seconds))return '00:00';seconds=Math.max(0,seconds);const h=Math.floor(seconds/3600),m=Math.floor(seconds/60)%60,s=Math.floor(seconds%60);return `${h?h.toString().padStart(2,'0')+':':''}${m.toString().padStart(2,'0')}:${s.toString().padStart(2,'0')}${decimal?'.'+Math.floor((seconds%1)*10):''}`;}
export function parseSubtitles(text,duration=Infinity){const result=[];const blocks=text.replace(/^\uFEFF/,'').replace(/\r/g,'').split(/\n\s*\n/);const time=s=>s.trim().replace(',','.').split(':').map(Number).reduce((a,b)=>a*60+b,0);for(const block of blocks){const lines=block.trim().split('\n');const i=lines.findIndex(l=>l.includes('-->'));if(i<0)continue;const match=lines[i].match(/((?:\d{1,3}:)?\d{2}:\d{2}[.,]\d{1,3})\s*-->\s*((?:\d{1,3}:)?\d{2}:\d{2}[.,]\d{1,3})/);if(!match)continue;const start=time(match[1]),end=Math.min(duration,time(match[2]));const content=lines.slice(i+1).join('\n').replace(/<[^>]*>/g,'').replace(/\{[^}]*\}/g,'').trim();if(Number.isFinite(start)&&Number.isFinite(end)&&start>=0&&end>start&&content)result.push({start,end,text:content});}return result.sort((a,b)=>a.start-b.start);}
export function subtitleSignal(cues,start,end){const relevant=cues.filter(c=>c.end>start&&c.start<end);const text=relevant.map(c=>c.text).join(' ');const words=(text.match(/[!?！？]|为什么|不可能|快跑|救命|永远|再见|真相|相信|必须|危险|爱你|别走|help|never|run|truth|love|why|please/gi)||[]).length;return {text,signal:text?clamp(.3+words*.16+Math.min(text.length,100)/400,0,1):0};}
export function makeCandidates(samples,cues,duration,style='dynamic'){if(!samples.length)return [];const length=Math.min(duration,style==='dialogue'?8:4);const maxDelta=Math.max(8,...samples.map(s=>s.delta));const ranked=samples.map((s,i)=>{let start=clamp(s.time-length*.4,0,Math.max(0,duration-length)),end=Math.min(duration,start+length);const sub=subtitleSignal(cues,start,end),motion=clamp(s.delta/maxDelta,0,1);if(style==='dialogue'&&sub.text){const nearby=cues.filter(c=>c.end>start&&c.start<end);start=Math.max(0,nearby[0].start-.2);end=Math.min(duration,nearby.at(-1).end+.25,start+14);}const score=Math.round((style==='dialogue'?(motion*.25+sub.signal*.75):(motion*.78+sub.signal*.22))*100);return {id:`clip-${i}`,start,end,score,motion:Math.round(motion*100),dialogue:Math.round(sub.signal*100),title:sub.text?sub.text.replace(/\n/g,' ').slice(0,25):`画面节奏 ${String(i+1).padStart(2,'0')}`,text:sub.text,thumb:s.thumb,reason:sub.text?'画面变化 + 对白线索':'画面变化峰值'};}).sort((a,b)=>b.score-a.score);const picked=[];for(const c of ranked){if(!picked.some(p=>Math.min(p.end,c.end)-Math.max(p.start,c.start)>0))picked.push(c);if(picked.length>=18)break;}return picked.sort((a,b)=>b.score-a.score);}
export function chooseClips(candidates,target){let remaining=target;const picked=[];for(const c of candidates){if(remaining<.5)break;const d=Math.min(c.end-c.start,remaining);if(d<.5)continue;picked.push({...c,end:c.start+d});remaining-=d;}return picked.sort((a,b)=>a.start-b.start);}
export function validRange(start,end,duration){return Number.isFinite(start)&&Number.isFinite(end)&&start>=0&&end<=duration+.001&&end-start>=.1;}
